def seed_reporting(apps, schema_editor):
    Student = apps.get_model('core', 'Student')
    Enrollment = apps.get_model('core', 'Enrollment')
    Tariff = apps.get_model('core', 'StudentTariff')
    alias = schema_editor.connection.alias
    states = {'active': 'active', 'pending': 'planned', 'inactive': 'left', 'graduated': 'completed'}
    for student in Student.objects.using(alias).select_related('group').iterator():
        Student.objects.using(alias).filter(pk=student.pk).update(public_id=uuid.uuid4())
        Tariff.objects.using(alias).filter(student_id=student.pk).update(due_day=student.registration_date.day)
        if student.group_id:
            Enrollment.objects.using(alias).create(
                student_id=student.pk, group_id=student.group_id,
                status=states[student.status], starts_on=student.registration_date,
                is_primary=True, mirrors_student=True,
                monthly_fee=max(0, student.group.monthly_fee * (100 - student.discount_percent) / 100),
                due_day=student.registration_date.day,
            )



